do $$ declare src uuid:=(select id from public.generation_assets where generation_id='30000000-0000-4000-8000-000000000001'); payload jsonb; p uuid; j public.compute_jobs; begin
 payload:='{"mode":"text_to_video","prompt":"prompt","negative_prompt":"","body_type":"none","identity_id":null,"source_generation_asset_id":null,"requested_duration_seconds":10,"motion_strength":0.4}';
 select project_id into p from public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001',null,null,'prompt-standard',repeat('1',64),payload,'standard'); assert (select identity_id is null and segment_count=2 from public.video_projects where id=p); select * into j from public.compute_jobs where id=(select video_job_id from public.video_projects where id=p); assert j.request_payload->'identity_id'='null' and j.request_payload->'identity_reference'='null' and j.request_payload->>'target_fps'='30' and j.request_payload->>'target_min_short_edge'='1080';
 payload:=jsonb_set(jsonb_set(payload,'{requested_duration_seconds}','25'),'{motion_strength}','1'); perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001',null,null,'prompt-og',repeat('2',64),payload,'og'); assert (select segment_count=3 from public.video_projects where idempotency_key='prompt-og');
 payload:=jsonb_set(jsonb_set(payload,'{requested_duration_seconds}','10'),'{motion_strength}','0.65'); payload:=jsonb_set(payload,'{identity_id}','"20000000-0000-4000-8000-000000000001"'); select project_id into p from public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'twin',repeat('3',64),payload,'standard'); select * into j from public.compute_jobs where id=(select video_job_id from public.video_projects where id=p); assert j.request_payload->'identity_reference'=jsonb_build_object('id','20000000-0000-4000-8000-000000000001'::uuid,'bucket','private-bucket','key','twins/one.safetensors','trigger_token','TOKEN');
 foreach p in array array['20000000-0000-4000-8000-000000000002'::uuid,'20000000-0000-4000-8000-000000000003'::uuid,'20000000-0000-4000-8000-000000000004'::uuid,'20000000-0000-4000-8000-000000000005'::uuid,'20000000-0000-4000-8000-000000000099'::uuid] loop begin payload:=jsonb_set(payload,'{identity_id}',to_jsonb(p)); perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001',p,null,'bad-'||p,repeat('4',64),payload,'standard'); raise exception 'bad Twin accepted'; exception when others then assert sqlerrm like '%VIDEO_IDENTITY_NOT_READY%'; end; end loop;
 payload:='{"mode":"image_to_video","prompt":"","negative_prompt":"","body_type":"none","identity_id":null,"source_generation_asset_id":"'||src||'","requested_duration_seconds":10,"motion_strength":0.8}'; perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001',null,src,'generated-source',repeat('5',64),payload,'standard');
 begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000002',null,src,'foreign-source',repeat('6',64),payload,'standard');raise exception 'foreign accepted';exception when others then assert sqlerrm like '%VIDEO_SOURCE_INVALID%';end;
 begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001',null,null,'missing-source',repeat('7',64),jsonb_set(payload,'{source_generation_asset_id}','null'),'standard');raise exception 'missing accepted';exception when others then assert sqlerrm like '%VIDEO_SOURCE_INVALID%';end;
 begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001',null,src,'text-source',repeat('8',64),jsonb_set(payload,'{mode}','"text_to_video"'),'standard');raise exception 'text source accepted';exception when others then assert sqlerrm like '%VIDEO_SOURCE_MODE_INVALID%';end;
 foreach payload in array array[jsonb_set(jsonb_set(payload,'{requested_duration_seconds}','9'),'{source_generation_asset_id}',to_jsonb(src)),jsonb_set(jsonb_set(payload,'{motion_strength}','0.81'),'{source_generation_asset_id}',to_jsonb(src))] loop begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001',null,src,gen_random_uuid()::text,repeat('9',64),payload,'standard');raise exception 'tier violation accepted';exception when others then assert sqlerrm like '%VIDEO_TIER_INVALID%';end;end loop;
 perform public.cancel_video_project('10000000-0000-4000-8000-000000000001',(select id from public.video_projects where idempotency_key='prompt-og')); assert (select cancellation_requested_at is not null from public.video_projects where idempotency_key='prompt-og');
 begin perform public.submit_compute_job('10000000-0000-4000-8000-000000000001','video','generic',repeat('a',64),'{}','standard');raise exception 'generic Video accepted';exception when others then assert sqlerrm like '%WORKLOAD_SUBMISSION_REQUIRED%';end;
end$$;

